partial class Canvas {
 public void TestPathSelection(){StartVectorBox();TestDrag(new Point(20,40),new Point(160,80));if(selectedPaths.Count!=1)throw new Exception("Vector box select");PickVector(new PointF(280,160),Keys.Shift);VectorUp(new PointF(280,160));if(selectedPaths.Count!=2)throw new Exception("Shift-add path");PickVector(new PointF(80,60),Keys.Control);if(selectedPaths.Count!=1||selectedVector.Points[0].X!=240)throw new Exception("Ctrl-remove path");SelectPathsInBox(new RectangleF(0,0,180,100),Keys.Shift);if(selectedPaths.Count!=2)throw new Exception("Box add");SelectPathsInBox(new RectangleF(200,100,180,100),Keys.Control);if(selectedPaths.Count!=1)throw new Exception("Box subtract");var square=RectanglePoints(new PointF(10,10),new PointF(110,60),true);if(square[2]!=new PointF(110,110))throw new Exception("Shift square");}
 public void TestAllShapePoints(){foreach(string kind in new[]{"Line","Ellipse","Polygon","Closed curve"}){CancelVector();var shape=new VectorShape{Kind=kind,Colour=Color.Blue};shape.Points=kind=="Ellipse"?new List<PointF>{new PointF(100,100),new PointF(300,200)}:new List<PointF>{new PointF(100,100),new PointF(200,200),new PointF(300,100),new PointF(350,200)};Doc.Selected.Vectors.Add(shape);selectedVector=shape;AddSelectedPath(shape);var grips=shape.Grips();SelectVectorPoint(0,false);SelectVectorPoint(1,true);PointF midpoint=new PointF((grips[0].X+grips[1].X)/2,(grips[0].Y+grips[1].Y)/2);int before=grips.Length;EditCurvePoint(true);if(shape.Points.Count!=before+1||!shape.Points.Contains(midpoint))throw new Exception("Add shape point "+kind);EditCurvePoint(false);if(shape.Points.Count!=before)throw new Exception("Remove shape point "+kind);TestDraftPaint();}string path=System.IO.Path.Combine(System.IO.Path.GetTempPath(),Guid.NewGuid()+".idsk");try{Doc.Save(path);using(var loaded=Document.Load(path))if(!loaded.Selected.Vectors.Any(v=>v.Kind=="Closed curve"))throw new Exception("Edited ellipse persistence");}finally{if(System.IO.File.Exists(path))System.IO.File.Delete(path);}CancelVector();}
 readonly HashSet<VectorShape> selectedPaths=new HashSet<VectorShape>();public bool VectorBoxMode;bool vectorBoxDragging;PointF vectorBoxStart,vectorBoxEnd;Keys vectorBoxModifiers;
 static int MinimumShapePoints(VectorShape shape){return shape.Kind=="Polygon"||shape.Kind=="Ellipse"||shape.Kind=="Closed curve"?3:2;}
 static List<PointF> RectanglePoints(PointF a,PointF b,bool square){if(square){float side=Math.Max(Math.Abs(b.X-a.X),Math.Abs(b.Y-a.Y));b=new PointF(a.X+(b.X<a.X?-side:side),a.Y+(b.Y<a.Y?-side:side));}return new List<PointF>{a,new PointF(b.X,a.Y),b,new PointF(a.X,b.Y)};}
 public void StartVectorBox(){EndStroke();draft=null;VectorBoxMode=true;vectorBoxDragging=false;NotifyVectorBox();RefreshCursor();}
 bool VectorBoxDown(PointF p){if(Doc==null||!Doc.Selected.IsVector||!VectorBoxMode)return false;vectorBoxStart=vectorBoxEnd=p;vectorBoxModifiers=ModifierKeys;vectorBoxDragging=true;Capture=true;Invalidate();return true;}
 bool VectorBoxMove(PointF p){if(!vectorBoxDragging)return false;vectorBoxEnd=p;Invalidate();return true;}
 bool VectorBoxUp(PointF p){if(!vectorBoxDragging)return false;vectorBoxEnd=p;vectorBoxDragging=false;VectorBoxMode=false;NotifyVectorBox();Capture=false;var rect=RectangleF.FromLTRB(Math.Min(vectorBoxStart.X,p.X),Math.Min(vectorBoxStart.Y,p.Y),Math.Max(vectorBoxStart.X,p.X),Math.Max(vectorBoxStart.Y,p.Y));SelectPathsInBox(rect,vectorBoxModifiers);return true;}
 public void SelectPathsInBox(RectangleF rect,Keys modifiers){if((modifiers&(Keys.Control|Keys.Shift))==0)ClearSelectedPaths();foreach(var shape in Doc.Selected.Vectors){bool hit=false;using(var path=shape.Path()){if(path.PointCount<2)continue;if(shape.HasFill){using(var region=new Region(path))hit=region.IsVisible(rect);}using(var pen=new Pen(Color.Black,Math.Max(1,shape.Width))){path.Widen(pen);using(var region=new Region(path))hit=hit||region.IsVisible(rect);}}if(hit){if((modifiers&Keys.Control)!=0){foreach(var member in Doc.Selected.Vectors.Where(v=>v==shape||shape.GroupId!=""&&v.GroupId==shape.GroupId))RemoveSelectedPath(member);}else AddSelectedPath(shape);}}ExpandSelectedGroups();selectedVector=Doc.Selected.Vectors.LastOrDefault(v=>selectedPaths.Contains(v));selectedPoints.Clear();if(selectedVector!=null&&VectorSelected!=null)VectorSelected();NotifyPointSelection();Invalidate();}
 bool PickVector(PointF p,Keys modifiers){bool control=(modifiers&Keys.Control)!=0,shift=(modifiers&Keys.Shift)!=0;var hit=Doc.Selected.Vectors.LastOrDefault(v=>v.Hit(p,7/Zoom));if(control){if(hit!=null)foreach(var member in Doc.Selected.Vectors.Where(v=>v==hit||hit.GroupId!=""&&v.GroupId==hit.GroupId))RemoveSelectedPath(member);ExpandSelectedGroups();selectedVector=Doc.Selected.Vectors.LastOrDefault(v=>selectedPaths.Contains(v));selectedPoints.Clear();if(selectedVector!=null&&VectorSelected!=null)VectorSelected();NotifyPointSelection();Invalidate();return true;}
  if(!shift&&PickPointHandle(p))return true;if((modifiers&Keys.Alt)!=0&&hit!=null){if(!selectedPaths.Contains(hit))ClearSelectedPaths();AddSelectedPath(hit);ExpandSelectedGroups();selectedVector=hit;selectedPoints.Clear();vectorHandle=-1;StartVectorDrag(p);duplicateVectorOnDrag=true;NotifyPointSelection();return true;}if(selectedVector!=null&&selectedPaths.Count==1){var grips=selectedVector.Grips();if(StrokeSession.Distance(VectorRotationGrip(),p)*Zoom<14){vectorHandle=-3;StartVectorDrag(p);return true;}for(int i=0;i<grips.Length;i++)if(StrokeSession.Distance(grips[i],p)*Zoom<10){SelectVectorPoint(i,shift);vectorHandle=i;StartVectorDrag(p);return true;}}
  if(hit==null){if(!shift){ClearSelectedPaths();selectedVector=null;selectedPoints.Clear();}NotifyPointSelection();VectorBoxMode=true;VectorBoxDown(p);vectorBoxModifiers=modifiers;Invalidate();return true;}if(!shift&&!selectedPaths.Contains(hit))ClearSelectedPaths();AddSelectedPath(hit);ExpandSelectedGroups();selectedVector=hit;selectedPoints.Clear();if(VectorSelected!=null)VectorSelected();vectorHandle=-1;if(selectedPaths.Count==1){var grips=hit.Grips();for(int j=0;j<grips.Length;j++)if(StrokeSession.Distance(grips[j],p)*Zoom<10){SelectVectorPoint(j,false);vectorHandle=j;break;}}StartVectorDrag(p);NotifyPointSelection();Invalidate();return true;
 }
 bool duplicateVectorOnDrag;void StartVectorDrag(PointF p){duplicateVectorOnDrag=false;vectorDragging=true;vectorChanged=false;vectorLast=SnapVectorPoint(p);BeginPointAxis();Capture=true;Invalidate();}
 RectangleF SelectedPathsBounds(){RectangleF bounds=RectangleF.Empty;foreach(var shape in selectedPaths)bounds=bounds.IsEmpty?shape.Bounds():RectangleF.Union(bounds,shape.Bounds());return bounds;}
 void PaintPathSelection(Graphics g){using(var pen=new Pen(Color.Teal,1/Zoom)){pen.DashStyle=DashStyle.Dash;if(selectedPaths.Count>1)foreach(var shape in selectedPaths){var b=shape.Bounds();g.DrawRectangle(pen,b.X,b.Y,b.Width,b.Height);}if(vectorBoxDragging){var b=RectangleF.FromLTRB(Math.Min(vectorBoxStart.X,vectorBoxEnd.X),Math.Min(vectorBoxStart.Y,vectorBoxEnd.Y),Math.Max(vectorBoxStart.X,vectorBoxEnd.X),Math.Max(vectorBoxStart.Y,vectorBoxEnd.Y));g.DrawRectangle(pen,b.X,b.Y,b.Width,b.Height);}}}
}
